{"title":"Adaptive-RAG: Learning to Adapt Retrieval-Augmented Large Language Models through Question Complexity","url":"https://arxiv.org/abs/2403.14403","arxiv_id":"2403.14403","authors":["Soyeong Jeong","Jinheon Baek","Sukmin Cho","Sung Ju Hwang","Jong C. Park"],"year":2024,"published":"2024-03-21","abstract":"Adaptive-RAG learns to route questions among no-retrieval, single-step retrieval, and iterative retrieval strategies according to predicted question complexity, providing a direct adaptive controller over retrieval depth.","venue":"NAACL 2024"}
{"title":"DeepRAG: Thinking to Retrieve Step by Step for Large Language Models","url":"https://arxiv.org/abs/2502.01142","arxiv_id":"2502.01142","authors":["Xinyan Guan","Jiali Zeng","Fandong Meng","Chunlei Xin","Yaojie Lu","Hongyu Lin","Xianpei Han","Le Sun","Jie Zhou"],"year":2025,"published":"2025-02-03","abstract":"DeepRAG formulates retrieval-augmented reasoning as a Markov decision process and decomposes complex questions while dynamically deciding at each reasoning step whether to retrieve external evidence or rely on parametric knowledge.","venue":"arXiv"}
{"title":"Corrective Retrieval Augmented Generation","url":"https://arxiv.org/abs/2401.15884","arxiv_id":"2401.15884","authors":["Shi-Qi Yan","Jia-Chen Gu","Yun Zhu","Zhen-Hua Ling"],"year":2024,"published":"2024-01-29","abstract":"CRAG introduces a lightweight retrieval evaluator that estimates retrieval quality and triggers corrective actions, including additional external search and decomposition-recomposition of retrieved material when the initial evidence is unreliable.","venue":"arXiv"}
{"title":"Adaptive Retrieval-Augmented Generation for Conversational Systems","url":"https://arxiv.org/abs/2407.21712","arxiv_id":"2407.21712","doi":"10.18653/v1/2025.findings-naacl.30","authors":["Xi Wang","Procheta Sen","Ruizhe Li","Emine Yilmaz"],"year":2025,"published":"2024-07-31","abstract":"The paper introduces RAGate, which predicts for each conversational turn whether external retrieval is needed rather than always invoking RAG, using human judgments of retrieval necessity to train and evaluate the gate.","venue":"Findings of NAACL 2025"}
{"title":"CtrlA: Adaptive Retrieval-Augmented Generation via Inherent Control","url":"https://arxiv.org/abs/2405.18727","arxiv_id":"2405.18727","authors":["Huanshuo Liu","Hao Zhang","Zhijiang Guo","Jing Wang","Kuicai Dong","Xiangyang Li","Yi Quan Lee","Cong Zhang","Yong Liu"],"year":2024,"published":"2024-05-29","abstract":"CtrlA extracts representation-level signals associated with model honesty and confidence and uses them to control when retrieval should occur and how retrieval queries should be formulated.","venue":"arXiv"}
{"title":"Towards Adaptive Memory-Based Optimization for Enhanced Retrieval-Augmented Generation","url":"https://arxiv.org/abs/2504.05312","arxiv_id":"2504.05312","authors":["Qitao Qin","Yucong Luo","Yihang Lu","Zhibo Chu","Xiaoman Liu","Xianwei Meng"],"year":2025,"published":"2025-02-19","abstract":"Amber combines an agent-memory updater, adaptive information collector, and filtering mechanism so that retrieval queries evolve with accumulated evidence and information collection can terminate when the system judges that enough knowledge has been gathered.","venue":"Findings of ACL 2025"}
{"title":"ReflectiveRAG: Rethinking Adaptivity in Retrieval-Augmented Generation","url":"https://aclanthology.org/2026.eacl-industry.27/","doi":"10.18653/v1/2026.eacl-industry.27","authors":["Akshay Verma","Swapnil Gupta","Siddharth Pillai","Prateek Sircar","Deepak Gupta"],"year":2026,"abstract":"ReflectiveRAG uses a small controller to iteratively assess evidence sufficiency, reformulate retrieval when evidence is inadequate, and filter redundant or tangential context, with experiments including heavy distractor noise.","venue":"EACL 2026 Industry Track"}
{"title":"CORAL: Adaptive Retrieval Loop for Culturally-Aligned Multilingual RAG","url":"https://aclanthology.org/2026.findings-acl.1356/","doi":"10.18653/v1/2026.findings-acl.1356","authors":["Nayeon Lee","Jiwoo Song","Byeongcheol Kang"],"year":2026,"abstract":"CORAL implements an iterative loop over corpus selection, retrieval, evidence critique, and sufficiency checking; when evidence is insufficient it can select another corpus and rewrite the query before another retrieval round.","venue":"Findings of ACL 2026"}
{"title":"SPARKLE: A Structured and Plug-and-play Agentic Retrieval Policy for Adaptive RAG Models","url":"https://aclanthology.org/2026.acl-long.1793/","doi":"10.18653/v1/2026.acl-long.1793","authors":["Jinyuan Fang","Zaiqiao Meng","Craig Macdonald"],"year":2026,"abstract":"SPARKLE trains a proxy-model controller with reinforcement learning and structured knowledge-graph reasoning to make adaptive retrieval-policy decisions independently of the downstream retriever and language model.","venue":"ACL 2026"}
{"title":"Interpretable Uncertainty for Adaptive Retrieval and Reasoning in Question Answering","url":"https://arxiv.org/abs/2607.07380","arxiv_id":"2607.07380","authors":["Ritajit Dey","Iadh Ounis","Graham McDonald"],"year":2026,"published":"2026-07-08","abstract":"The method decomposes uncertainty into knowledge insufficiency and ambiguity or conflict, using the former to trigger retrieval and the latter to trigger additional reasoning, thereby tying adaptive actions to interpretable uncertainty signals.","venue":"arXiv"}
{"title":"When to Retrieve During Reasoning: Adaptive Retrieval for Large Reasoning Models","url":"https://arxiv.org/abs/2604.26649","arxiv_id":"2604.26649","doi":"10.1145/3805712.3809722","authors":["Dongxin Guo","Jikun Wu","Siu Ming Yiu"],"year":2026,"published":"2026-04-29","abstract":"ReaLM-Retrieve detects step-level knowledge gaps during reasoning and learns a retrieval-intervention policy that decides when external evidence should be acquired instead of retrieving at fixed intervals.","venue":"SIGIR 2026"}
{"title":"Metacognitive Retrieval-Augmented Large Language Models","url":"https://arxiv.org/abs/2402.11626","arxiv_id":"2402.11626","doi":"10.1145/3589334.3645481","authors":["Yujia Zhou","Zheng Liu","Jiajie Jin","Jian-Yun Nie","Zhicheng Dou"],"year":2024,"published":"2024-02-18","abstract":"MetaRAG adds metacognitive monitoring, evaluation, and planning to retrieval-augmented reasoning so that the model can identify deficiencies in its current response and adaptively repair them rather than following a fixed reasoning trajectory.","venue":"The Web Conference 2024"}
{"title":"Knowing You Don't Know: Learning When to Continue Search in Multi-round RAG through Self-Practicing","url":"https://arxiv.org/abs/2505.02811","arxiv_id":"2505.02811","doi":"10.1145/3726302.3730018","authors":["Diji Yang","Linda Zeng","Jinmeng Rao","Yi Zhang"],"year":2025,"published":"2025-05-05","abstract":"SIM-RAG trains a lightweight information-sufficiency critic through self-practicing so that each retrieval round can decide whether accumulated evidence is sufficient or whether search should continue.","venue":"SIGIR 2025"}
{"title":"Adaptive Stopping for Multi-Turn LLM Reasoning","url":"https://arxiv.org/abs/2604.01413","arxiv_id":"2604.01413","authors":["Xiaofan Zhou","Huy Nguyen","Bo Yu","Chenxi Liu","Lu Cheng"],"year":2026,"published":"2026-04-01","abstract":"The paper develops a multi-turn conformal-prediction framework that allocates error budgets across sequential reasoning steps and supports early stopping in settings including adaptive RAG and ReAct while maintaining an overall coverage target.","venue":"arXiv"}
{"title":"Entropic Claim Resolution: Uncertainty-Driven Evidence Selection for RAG","url":"https://arxiv.org/abs/2603.28444","arxiv_id":"2603.28444","authors":["Davide Di Gioia"],"year":2026,"published":"2026-03-30","abstract":"The method sequentially selects atomic evidence claims according to expected uncertainty reduction and terminates acquisition at an explicit epistemic-sufficiency condition, connecting retrieval selection with a value-of-information style stopping rule.","venue":"arXiv"}
{"title":"Agent-Orchestrated Adaptive RAG: A Comparative Study on Structured and Multi-Hop Retrieval","url":"https://arxiv.org/abs/2606.05658","arxiv_id":"2606.05658","authors":["Anuj Maharjan","Devinder Kaur","Richard Molyet"],"year":2026,"published":"2026-06-04","abstract":"This study evaluates an agentic RAG architecture using dynamic query decomposition, iterative retrieval, and a bounded self-reflective evaluation loop, including experiments on a domain-specific DevOps knowledge base and multi-hop QA.","venue":"arXiv"}
{"title":"RAG-on-a-Diet: A Reinforcement Learning-Based Dynamic Resource Optimization Framework for RAG","url":"https://aclanthology.org/2026.acl-long.1562/","doi":"10.18653/v1/2026.acl-long.1562","authors":["Hongwen Ding","Yizheng Zhao"],"year":2026,"abstract":"RAG-on-a-Diet uses reinforcement learning to make per-hop resource decisions from entity and confidence features under a cost-aware objective, with explicit termination based on a hop bound and confidence gate and evaluation that includes out-of-domain data.","venue":"ACL 2026"}
{"title":"Cost-Aware Query Routing in RAG: Empirical Analysis of Retrieval Depth Tradeoffs","url":"https://arxiv.org/abs/2606.02581","arxiv_id":"2606.02581","doi":"10.3390/ai7070250","authors":["Sanjay Mishra","Ganesh R. Naik"],"year":2026,"published":"2026-07-06","abstract":"The paper routes individual queries among retrieval configurations ranging from no retrieval to deeper retrieval by trading estimated answer quality against latency and billed-token costs, making retrieval depth a query-dependent decision.","venue":"AI"}
{"title":"Baikal: Structured Search for Deep Research over Data Lakes","url":"https://arxiv.org/abs/2607.27726","arxiv_id":"2607.27726","authors":["Dhruv Agarwal","Rishitha Guttapalle Mohan","Aarti Kumari","Ashi Sinha","Athulya Anil","Kavitha Srinivas","Horst Samulowitz","Andrew McCallum"],"year":2026,"published":"2026-07-30","abstract":"Baikal casts deep research over heterogeneous data lakes as budgeted search over semantic evidence regions, generating region-grounded subquestions and using value estimates to adaptively balance exploration and exploitation under a fixed investigation budget.","venue":"arXiv"}
{"title":"ROSE-RAG: Robust Sequential Evidence Acquisition for Agentic Retrieval-augmented Generation under Source-model Ambiguity","url":"https://papers.ssrn.com/sol3/papers.cfm?abstract_id=7172681","authors":["Arian Mokhtari","Maziar Davoodi"],"year":2026,"abstract":"ROSE-RAG models evidence acquisition as a sequential decision problem that jointly chooses whether to retrieve, which source to query, when to stop, and whether to answer or abstain while accounting for source reliability, acquisition cost, downstream loss, and ambiguity in the source model.","venue":"SSRN"}
{"title":"EVIDENCE-GATED SCIENTIFIC QA WITH EXPLICIT ABSTENTION AND PAGE-LEVEL PROVENANCE","url":"https://openreview.net/pdf?id=HW4dYquzhn","authors":["Bruno Leonardo Santos Menezes","Fábio Porto"],"year":2026,"abstract":"Pororoca conditions scientific answer generation on an explicit evidence-sufficiency gate, abstains when the evidence does not meet the gate, and retains document- and page-level provenance; its evaluation includes selective risk and retrieval-noise conditions.","venue":"ICLR 2026 Workshop on Foundation Models for Science: Real-World Impact and Science-First Design"}
{"title":"Do LLMs Know When Evidence is Insufficient? An Evidence Sufficiency Benchmark for Answer-Abstention Calibration in Retrieval-Augmented Generation","url":"https://www.techscience.com/cmc/v89n1/68467/html","doi":"10.32604/cmc.2026.086343","authors":["Hantian Zhang","Wentai Wu"],"year":2026,"published":"2026-08-13","abstract":"The benchmark evaluates whether RAG systems appropriately answer or abstain under full, partial, irrelevant, absent, and conflicting evidence, directly probing calibration to evidence sufficiency rather than ordinary answer accuracy alone.","venue":"Computers, Materials & Continua"}
{"title":"Controlling Risk of Retrieval-augmented Generation: A Counterfactual Prompting Framework","url":"https://arxiv.org/abs/2409.16146","arxiv_id":"2409.16146","doi":"10.18653/v1/2024.findings-emnlp.133","authors":["Lu Chen","Ruqing Zhang","Jiafeng Guo","Yixing Fan","Xueqi Cheng"],"year":2024,"published":"2024-09-24","abstract":"This work treats refusal as a mechanism for controlling RAG risk and uses counterfactual prompting to probe retrieval quality and the model's use of evidence, introducing evaluation with abstention and risk-oriented metrics.","venue":"Findings of EMNLP 2024"}
{"title":"C-RAG: Certified Generation Risks for Retrieval-Augmented Language Models","url":"https://arxiv.org/abs/2402.03181","arxiv_id":"2402.03181","authors":["Mintong Kang","Nezihe Merve Gürel","Ning Yu","Dawn Song","Bo Li"],"year":2024,"published":"2024-02-05","abstract":"C-RAG applies conformal risk analysis to retrieval-augmented generation to provide an upper confidence bound on a bounded generation-risk function and studies the resulting guarantees under test-distribution shifts.","venue":"ICML 2024"}
{"title":"Response Quality Assessment for Retrieval-Augmented Generation via Conditional Conformal Factuality","url":"https://arxiv.org/abs/2506.20978","arxiv_id":"2506.20978","doi":"10.1145/3726302.3730244","authors":["Naihe Feng","Yi Sui","Shiyi Hou","Jesse C. Cresswell","Ga Wu"],"year":2025,"published":"2025-06-26","abstract":"Conformal-RAG assesses response and subclaim quality with conformal techniques that provide statistical reliability guarantees, including group-conditional guarantees, without requiring a reference answer for every generated response.","venue":"SIGIR 2025"}
{"title":"Principled Context Engineering for RAG: Statistical Guarantees via Conformal Prediction","url":"https://arxiv.org/abs/2511.17908","arxiv_id":"2511.17908","doi":"10.1007/978-3-032-21300-6_45","authors":["Debashish Chakraborty","Eugene Yang","Daniel Khashabi","Dawn Lawrie","Kevin Duh"],"year":2026,"published":"2025-11-22","abstract":"The paper applies conformal prediction to retrieved-context selection, filtering noisy material while targeting statistical coverage of relevant evidence and thereby providing a principled reliability layer for RAG context construction.","venue":"ECIR 2026"}
{"title":"When Can Conformal Risk Control Certify LLM Outputs? Bounds, Impossibility, and Adaptation for Structured Generation","url":"https://arxiv.org/abs/2606.29054","arxiv_id":"2606.29054","authors":["Varun Kotte"],"year":2026,"published":"2026-06-27","abstract":"The paper derives limits on conformal risk control for structured LLM generation, including conditions requiring abstention when base risk is too high, and examines adaptive conformal procedures under cross-dataset distribution shift.","venue":"arXiv"}
{"title":"PromptShift-CRC: Drift-Aware Conformal Risk Control for Foundation Models Under Prompt and Domain Shift","url":"https://arxiv.org/abs/2606.15964","arxiv_id":"2606.15964","authors":["Jeffery Opoku","David Banahene"],"year":2026,"published":"2026-06-14","abstract":"PromptShift-CRC detects distributional drift and adapts conformal risk-control calibration through reweighting, recentering, and online risk updates, explicitly studying degradation of static calibration under prompt and domain shift.","venue":"arXiv"}
{"title":"Selective Question Answering under Domain Shift","url":"https://arxiv.org/abs/2006.09462","arxiv_id":"2006.09462","doi":"10.18653/v1/2020.acl-main.503","authors":["Amita Kamath","Robin Jia","Percy Liang"],"year":2020,"published":"2020-06-16","abstract":"This work studies selective question answering when deployment data mixes in-domain and out-of-domain examples, evaluating calibrators through risk-coverage behavior and showing why abstention calibration becomes difficult under domain shift.","venue":"ACL 2020"}
{"title":"Selective Classification Under Distribution Shifts","url":"https://arxiv.org/abs/2405.05160","arxiv_id":"2405.05160","authors":["Hengyue Liang","Le Peng","Ju Sun"],"year":2024,"published":"2024-05-08","abstract":"The paper studies selective classification across covariate, label, and out-of-distribution shifts and analyzes confidence-scoring strategies through their risk-coverage tradeoffs, providing transfer evidence for calibrated abstention under non-IID deployment.","venue":"arXiv"}
{"title":"Conformal Selective Prediction with General Risk Control","url":"https://arxiv.org/abs/2603.24704","arxiv_id":"2603.24704","authors":["Tian Bai","Ying Jin"],"year":2026,"published":"2026-03-25","abstract":"SCoRE develops selective prediction procedures with finite-sample control of general risk using conformal and hypothesis-testing ideas and extends the framework to distribution-shift settings and applications involving language models.","venue":"arXiv"}
{"title":"On optimum recognition error and reject tradeoff","url":"https://doi.org/10.1109/TIT.1970.1054406","doi":"10.1109/TIT.1970.1054406","authors":["C. K. Chow"],"year":1970,"published":"1970-01-31","abstract":"This foundational reject-option paper derives an optimal decision rule for trading recognition errors against rejected decisions and characterizes the relationship between error probability and reject probability.","venue":"IEEE Transactions on Information Theory"}
{"title":"IDCR: Information-Directed Conformal Retrieval","url":"https://proceedings.mlr.press/v337/nanivadekar26a.html","authors":["Manas Nanivadekar","Jatin Khanijoan","Swayam Kothekar","Mohd Amaan Khan"],"year":2026,"abstract":"IDCR selects documents according to their expected reduction of conformal predictive uncertainty rather than semantic similarity alone, while preserving distribution-free coverage; a marginal-gain gate can route uncertain retrieval decisions to a more expensive lookahead search.","venue":"Proceedings of the 42nd Conference on Uncertainty in Artificial Intelligence (UAI 2026)"}
{"title":"TimelyRAG: Semantic-Temporal Hybrid Retrieval for Time-Critical Question Answering in Overlapping-Evolving Documents","url":"https://arxiv.org/abs/2609.11572","arxiv_id":"2609.11572","authors":["Youngeun Nam","Joeun Kim","Hwanjun Song","Susik Yoon","Jae-Gil Lee","Byung Suk Lee"],"year":2026,"published":"2026-09-10","abstract":"TimelyRAG addresses corpora such as laws and policies where amendments create highly overlapping document versions, combining semantic and temporal ranking so queries retrieve version-appropriate evidence rather than merely the most semantically similar text.","venue":"arXiv"}
{"title":"RAG Meets Temporal Graphs: Time-Sensitive Modeling and Retrieval for Evolving Knowledge","url":"https://arxiv.org/abs/2510.13590","arxiv_id":"2510.13590","authors":["Jiale Han","Austin Cheung","Yubai Wei","Zheng Yu","Xusheng Wang","Bing Zhu","Yi Yang"],"year":2025,"published":"2025-10-15","abstract":"Temporal GraphRAG represents timestamped relations explicitly so identical facts at different times remain distinct, supports incremental corpus updates, and dynamically retrieves subgraphs constrained by both temporal and semantic query scope.","venue":"arXiv"}
{"title":"LiveVectorLake: A Real-Time Versioned Knowledge Base Architecture for Streaming Vector Updates and Temporal Retrieval","url":"https://arxiv.org/abs/2601.05270","arxiv_id":"2601.05270","authors":["Tarun Prajapati"],"year":2026,"abstract":"LiveVectorLake combines a hot vector index with a versioned data-lake tier, uses content-addressable change detection, retains complete version history, and routes point-in-time queries through versioned storage to support temporal retrieval and auditability.","venue":"arXiv"}
{"title":"Temporal Conjunctive Query Answering via Rewriting","url":"https://ojs.aaai.org/index.php/AAAI/article/view/33670","doi":"10.1609/aaai.v39i14.33670","authors":["Lukas Westhofen","Jean Christoph Jung","Daniel Neider"],"year":2025,"published":"2025-04-11","abstract":"This work formalizes temporal conjunctive query answering and rewrites structured conjunctions into temporal-logic queries, providing a mechanism for expressing multi-entity joins together with explicit temporal constraints.","venue":"AAAI 2025"}
{"title":"A Taxonomy of Time in Databases","url":"https://doi.org/10.1145/318898.318921","doi":"10.1145/318898.318921","authors":["Richard Snodgrass","Ilsoo Ahn"],"year":1985,"abstract":"The paper develops a foundational taxonomy for representing time in databases and distinguishes different temporal dimensions needed to describe evolving information, laying groundwork for later valid-time and transaction-time database semantics.","venue":"ACM SIGMOD 1985"}
{"title":"Time-based language models","url":"https://collaborate.princeton.edu/en/publications/time-based-language-models/","authors":["Xiaoyan Li","W. Bruce Croft"],"year":2003,"abstract":"The paper incorporates temporal evidence into language-model-based information retrieval and evaluates retrieval for queries whose relevance depends on recency or a particular time period, providing an early foundation for temporal IR.","venue":"CIKM 2003"}
{"title":"Why and Where: A Characterization of Data Provenance","url":"https://doi.org/10.1007/3-540-44503-X_20","doi":"10.1007/3-540-44503-X_20","authors":["Peter Buneman","Sanjeev Khanna","Wang-Chiew Tan"],"year":2001,"published":"2001-10-12","abstract":"This foundational database-provenance paper distinguishes forms of source provenance, including where data came from and why it appears in a result, and formalizes provenance for query answers over structured data.","venue":"ICDT 2001"}
{"title":"Provenance semirings","url":"https://doi.org/10.1145/1265530.1265535","doi":"10.1145/1265530.1265535","authors":["Todd J. Green","Grigoris Karvounarakis","Val Tannen"],"year":2007,"abstract":"The paper introduces semiring annotations as a compositional algebra for provenance, unifying lineage and several existing annotation semantics while allowing derivations to propagate through relational queries.","venue":"PODS 2007"}
{"title":"Access control and view generation for provenance graphs","url":"https://www.sciencedirect.com/science/article/abs/pii/S0167739X1500031X","doi":"10.1016/j.future.2015.01.014","authors":["Roxana Danger","Vasa Curcin","Paolo Missier","Jeremy Bryans"],"year":2015,"abstract":"The paper studies access-controlled provenance and generates semantically valid views of provenance graphs that hide restricted material while retaining as much permitted lineage information as possible.","venue":"Future Generation Computer Systems"}
{"title":"ACCESSPROV: Tracking the Provenance of Access Control Decisions","url":"https://www.usenix.org/conference/tapp17/workshop-program/presentation/capobianco","authors":["Frank Capobianco","Christian Skalka","Trent Jaeger"],"year":2017,"published":"2017-06-23","abstract":"ACCESSPROV records the inputs and derivations that influence authorization decisions, making the provenance of access-control outcomes explicit rather than treating permission decisions as opaque filtering.","venue":"9th USENIX Workshop on Theory and Practice of Provenance (TaPP 2017)"}
{"title":"LayerRAG-Bench: A Cross-Layer Reliability Benchmark for Agentic Retrieval-Augmented Generation","url":"https://arxiv.org/abs/2607.27353","arxiv_id":"2607.27353","authors":["Musa Shams"],"year":2026,"published":"2026-07-29","abstract":"LayerRAG-Bench injects enterprise-style cross-layer faults including stale evidence, missing tool outputs, denied permissions, corrupted metadata, and wrong-session context, showing that apparently grounded answers can still fail at authorization, evidence, tool-contract, or session layers.","venue":"arXiv"}
{"title":"Adaptive Retrieval Without Self-Knowledge? Bringing Uncertainty Back Home","url":"https://aclanthology.org/2025.acl-long.319/","doi":"10.18653/v1/2025.acl-long.319","authors":["Viktor Moskvoretskii","Maria Marina","Mikhail Salnikov","Nikolay Ivanov","Sergey Pletenev","Daria Galimzianova","Nikita Krayko","Vasily Konovalov","Irina Nikishina","Alexander Panchenko"],"year":2025,"abstract":"This systematic empirical study compares adaptive retrieval approaches with numerous uncertainty-estimation methods across question-answering quality, self-knowledge, and efficiency, finding that uncertainty signals can often provide competitive adaptive-retrieval decisions without complex pipelines.","venue":"ACL 2025"}
{"title":"Test-time Corpus Feedback: From Retrieval to RAG","url":"https://aclanthology.org/2026.findings-eacl.298/","doi":"10.18653/v1/2026.findings-eacl.298","authors":["Mandeep Rathee","Venktesh V","Sean MacAvaney","Avishek Anand"],"year":2026,"abstract":"This survey organizes adaptive retrieval and ranking methods by where test-time feedback originates and whether it updates the query, retrieved context, or document pool, emphasizing retrieval as an iterative and learnable component rather than a one-shot RAG stage.","venue":"Findings of EACL 2026"}
{"title":"A Reproducibility Study of Metacognitive Retrieval-Augmented Generation","url":"https://arxiv.org/abs/2604.19899","arxiv_id":"2604.19899","doi":"10.1145/3805712.3808551","authors":["Gabriel Iturra-Bocaz","Petra Galuscakova"],"year":2026,"published":"2026-04-21","abstract":"This reproduction examines MetaRAG's ability to handle multi-retrieval reasoning and stopping, adds reranking experiments, and compares it with the sufficiency-critic-based SIM-RAG; it confirms relative improvements while reporting reproducibility and robustness limitations.","venue":"SIGIR 2026"}
===END llm_candidates.jsonl===
